import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';

function App() {
  return (
    <Router>
      <div className="App">
        <Routes>
          <Route path="/" element={<h1>Bem-vindo ao App de Modelação!</h1>} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
